def solve_total():
    # dp[k][r] = number of k-digit sequences using {0, 1, 2, 8} with sum % 3 = r
    dp = [[0]*3 for _ in range(17)]
    dp[0][0] = 1
    for i in range(1, 17):
        for r in range(3):
            for digit in [0, 1, 2, 8]:
                dp[i][(r + digit) % 3] += dp[i-1][r]

    total_count = 0
    for d in range(1, 17):
        count_d = 0
        for d1 in [1, 2, 8]:
            count_d += dp[d-1][(-d1) % 3]
        total_count += count_d

    return total_count

print(f"Total count for d=1..16: {solve_total()}")

